catalog_script_client.script:
function onChange(control, oldValue, newValue, isLoading) {
    if (isLoading || !newValue) return;

    g_form.getReference('date', function(ref) {
        if (!ref) return;

        var raw = ref.date || ref.u_date || ref.start_date || ref.scheduled_date;
        if (!raw) return;

        var trainingDate;
        if (typeof raw === 'string') {
            var m = raw.match(/^(\d{4})-(\d{2})-(\d{2})/);
            if (m) {
                trainingDate = new Date(parseInt(m[1], 10), parseInt(m[2], 10) - 1, parseInt(m[3], 10));
            } else {
                trainingDate = new Date(raw);
            }
        } else {
            trainingDate = new Date(raw);
        }

        trainingDate.setHours(0, 0, 0, 0);
        var today = new Date();
        today.setHours(0, 0, 0, 0);

        var diffDays = Math.floor((trainingDate - today) / (1000 * 60 * 60 * 24));

        if (diffDays <= 0) {
            g_form.clearValue('date');
            g_form.showFieldMsg('date', 'The enrollment period has ended. You can only enroll up to one day before the training date.', 'error');
        } else {
            g_form.hideFieldMsg('date');
        }
    });
}
